(() => {
const refs = Object.create(null);
const nodeIds = [];
const sceneRoot = document.createElement("div");
sceneRoot.setAttribute("id", "c1122-runtime-scene-root");
sceneRoot.setAttribute("style", "display:flex;width:360px;height:800px");
sceneRoot.setAttribute("data-c1122-grid-wrapper", "");
document.appendChild(sceneRoot);
const node_0 = document.createElement("div");
node_0.setAttribute("id", "c1122-order-mixed-grid");
node_0.setAttribute("data-c1122-grid-node", "");
node_0.setAttribute("style", "position:absolute;left:0;top:0px;display:grid;box-sizing:border-box;width:30px;height:10px;grid-template-columns:10px 10px 10px;grid-template-rows:10px;grid-auto-rows:10px;grid-auto-flow:row;column-gap:0;row-gap:0;margin:0;padding:0;border:0;background-color:#edf1f7");
sceneRoot.appendChild(node_0);
refs["c1122-order-mixed-grid"] = node_0;
nodeIds.push("c1122-order-mixed-grid");
const node_1 = document.createElement("div");
node_1.setAttribute("id", "c1122-order-mixed-a");
node_1.setAttribute("data-c1122-grid-node", "");
node_1.setAttribute("style", "display:block;box-sizing:border-box;width:10px;height:10px;margin:0;padding:0;border:0;order:2;background-color:#2866f6");
refs["c1122-order-mixed-grid"].appendChild(node_1);
refs["c1122-order-mixed-a"] = node_1;
nodeIds.push("c1122-order-mixed-a");
const node_2 = document.createElement("div");
node_2.setAttribute("id", "c1122-order-mixed-b");
node_2.setAttribute("data-c1122-grid-node", "");
node_2.setAttribute("style", "display:block;box-sizing:border-box;width:10px;height:10px;margin:0;padding:0;border:0;order:-1;background-color:#e5484d");
refs["c1122-order-mixed-grid"].appendChild(node_2);
refs["c1122-order-mixed-b"] = node_2;
nodeIds.push("c1122-order-mixed-b");
const node_3 = document.createElement("div");
node_3.setAttribute("id", "c1122-order-mixed-c");
node_3.setAttribute("data-c1122-grid-node", "");
node_3.setAttribute("style", "display:block;box-sizing:border-box;width:10px;height:10px;margin:0;padding:0;border:0;order:0;background-color:#2b9a66");
refs["c1122-order-mixed-grid"].appendChild(node_3);
refs["c1122-order-mixed-c"] = node_3;
nodeIds.push("c1122-order-mixed-c");
return { sceneId:"order-mixed", rootId:"c1122-order-mixed-grid", nodeIds };
})()

